module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    // Stage 1: pairs -> 2-bit sums
    logic [1:0] p [8];
    // Stage 2: quads -> 3-bit sums
    logic [2:0] q [4];
    // Stage 3: octets -> 4-bit sums
    logic [3:0] o [2];

    always_comb begin
        for (int i = 0; i < 8; i++)
            p[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        for (int i = 0; i < 4; i++)
            q[i] = {1'b0, p[2*i]} + {1'b0, p[2*i+1]};
        for (int i = 0; i < 2; i++)
            o[i] = {1'b0, q[2*i]} + {1'b0, q[2*i+1]};
        count = {1'b0, o[0]} + {1'b0, o[1]};
    end
endmodule

module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    // Stage 1: weight-1 compression of x[14:0]
    logic [4:0] s, c;
    assign s[0] = x[0]  ^ x[1]  ^ x[2];
    assign c[0] = (x[0] & x[1]) | (x[2] & (x[0] ^ x[1]));
    assign s[1] = x[3]  ^ x[4]  ^ x[5];
    assign c[1] = (x[3] & x[4]) | (x[5] & (x[3] ^ x[4]));
    assign s[2] = x[6]  ^ x[7]  ^ x[8];
    assign c[2] = (x[6] & x[7]) | (x[8] & (x[6] ^ x[7]));
    assign s[3] = x[9]  ^ x[10] ^ x[11];
    assign c[3] = (x[9] & x[10]) | (x[11] & (x[9] ^ x[10]));
    assign s[4] = x[12] ^ x[13] ^ x[14];
    assign c[4] = (x[12] & x[13]) | (x[14] & (x[12] ^ x[13]));

    // Weight-1: s0..s4 and x15
    logic t, u0, v, u1, u2;
    assign t  = s[0] ^ s[1] ^ s[2];
    assign u0 = (s[0] & s[1]) | (s[2] & (s[0] ^ s[1]));
    assign v  = s[3] ^ s[4] ^ x[15];
    assign u1 = (s[3] & s[4]) | (x[15] & (s[3] ^ s[4]));
    assign count[0] = t ^ v;
    assign u2 = t & v;

    // Weight-2: c0..c4, u0, u1, u2
    logic p, q, r, w, y, z, h;
    assign p = c[0] ^ c[1] ^ c[2];
    assign q = (c[0] & c[1]) | (c[2] & (c[0] ^ c[1]));
    assign r = c[3] ^ c[4] ^ u0;
    assign w = (c[3] & c[4]) | (u0 & (c[3] ^ c[4]));
    assign y = u1 ^ u2 ^ p;
    assign z = (u1 & u2) | (p & (u1 ^ u2));
    assign count[1] = y ^ r;
    assign h = y & r;

    // Weight-4: q, w, z, h
    logic m, n, o;
    assign m = q ^ w ^ z;
    assign n = (q & w) | (z & (q ^ w));
    assign count[2] = m ^ h;
    assign o = m & h;

    // Weight-8 and 16
    assign count[3] = n ^ o;
    assign count[4] = n & o;
endmodule

module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    logic [1:0] p [8];
    logic [2:0] q [4];
    logic [3:0] r [2];

    always_comb begin
        for (int i = 0; i < 8; i++)
            p[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        for (int i = 0; i < 4; i++)
            q[i] = {1'b0, p[2*i]} + {1'b0, p[2*i+1]};
        for (int i = 0; i < 2; i++)
            r[i] = {1'b0, q[2*i]} + {1'b0, q[2*i+1]};
        count = {1'b0, r[0]} + {1'b0, r[1]};
    end
endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);
    logic [8:0] add_r;
    logic [8:0] sub_r;

    always_comb begin
        add_r = {1'b0, a} + {1'b0, b};
        sub_r = {1'b0, a} - {1'b0, b};
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = add_r[7:0];
                carry = add_r[8];
            end
            3'b001: begin
                y     = sub_r[7:0];
                carry = sub_r[8];
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = {7'd0, ($signed(a) < $signed(b))};
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
        zero = (y == 8'd0);
    end
endmodule

