module edge_detect (
    input  logic clk,
    input  logic rst,   // synchronous, active high
    input  logic din,
    output logic rise,
    output logic fall
);
    logic prev;

    always_ff @(posedge clk) begin
        if (rst) begin
            rise <= 1'b0;
            fall <= 1'b0;
            prev <= 1'b0;
        end else begin
            rise <= din & ~prev;
            fall <= ~din & prev;
            prev <= din;
        end
    end
endmodule

