    localparam int AW = (DEPTH > 1) ? $clog2(DEPTH) : 1;

    logic [W-1:0] mem [0:(1<<AW)-1];
    logic [AW-1:0] wptr, rptr;

    assign full  = (count == DEPTH[$clog2(DEPTH):0]);
    assign empty = (count == '0);

    logic do_wr, do_rd;
    assign do_wr = wr_en && !full;
    assign do_rd = rd_en && !empty;

    logic [AW-1:0] wptr_n, rptr_n;
    always_comb begin
        wptr_n = wptr + 1'b1;
        rptr_n = rptr + 1'b1;
        if (DEPTH == 1) begin
            wptr_n = '0;
            rptr_n = '0;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            wptr  <= '0;
            rptr  <= '0;
            count <= '0;
        end else begin
            if (do_wr) begin
                mem[wptr] <= din;
                wptr      <= wptr_n;
            end
            if (do_rd) begin
                dout <= mem[rptr];
                rptr <= rptr_n;
            end
            case ({do_wr, do_rd})
                2'b10:   count <= count + 1'b1;
                2'b01:   count <= count - 1'b1;
                default: count <= count;
            endcase
        end
    end
endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] pick;
    logic       found;

    always_comb begin
        found = 1'b0;
        pick  = 2'd0;
        for (int k = 1; k <= 4; k++) begin
            logic [1:0] idx;
            idx = 2'(last + 2'(k));
            if (!found && req[idx]) begin
                found = 1'b1;
                pick  = idx;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0;
            last <= 2'd3;
        end else if (!found) begin
            gnt <= 4'b0;
        end else begin
            gnt  <= 4'b1 << pick;
            last <= pick;
