    input  logic       rst,
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] pick;

    always_comb begin
        pick = 2'd0;
        case (last)
            2'd0: begin
                if      (req[1]) pick = 2'd1;
                else if (req[2]) pick = 2'd2;
                else if (req[3]) pick = 2'd3;
                else             pick = 2'd0;
            end
            2'd1: begin
                if      (req[2]) pick = 2'd2;
                else if (req[3]) pick = 2'd3;
                else if (req[0]) pick = 2'd0;
                else             pick = 2'd1;
            end
            2'd2: begin
                if      (req[3]) pick = 2'd3;
                else if (req[0]) pick = 2'd0;
                else if (req[1]) pick = 2'd1;
                else             pick = 2'd2;
            end
            default: begin
                if      (req[0]) pick = 2'd0;
                else if (req[1]) pick = 2'd1;
                else if (req[2]) pick = 2'd2;
                else             pick = 2'd3;
            end
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (req == 4'b0000) begin
            gnt <= 4'b0000;
        end else begin
            gnt  <= 4'b0001 << pick;
            last <= pick;
        end
    end
