module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);
    logic [$clog2(CLKS_PER_BIT)-1:0] cnt;
    logic [3:0] idx;
    logic [7:0] sh;

    always_ff @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            cnt  <= '0;
            idx  <= 4'd0;
            sh   <= 8'hFF;
        end else if (!busy) begin
            if (start) begin
                tx   <= 1'b0;
                busy <= 1'b1;
                cnt  <= '0;
                idx  <= 4'd0;
                sh   <= data;
            end
        end else begin
            if (cnt == CLKS_PER_BIT-1) begin
                cnt <= '0;
                if (idx == 4'd9) begin
                    busy <= 1'b0;
                    tx   <= 1'b1;
                end else begin
                    idx <= idx + 4'd1;
                    tx  <= sh[0];
                    sh  <= {1'b1, sh[7:1]};
                end
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end
endmodule

