module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] data [5];
    logic [2:0]   src  [5];
    logic [2:0]   cur  [5];

    logic [2:0]   dst  [5];      // requested output per input
    logic [4:0]   gv;
    logic [2:0]   gi   [5];

    // routing
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            logic [1:0] dx, dy;
            dx = in_flit[i*F + F-1 -: 2];
            dy = in_flit[i*F + F-3 -: 2];
            if (dx > X)      dst[i] = 3'd2;
            else if (dx < X) dst[i] = 3'd3;
            else if (dy > Y) dst[i] = 3'd0;
            else if (dy < Y) dst[i] = 3'd1;
            else             dst[i] = 3'd4;
        end
    end

    // arbitration
    always_comb begin
        in_ready = '0;
        for (int o = 0; o < 5; o++) begin
            logic [2:0] s, idx;
            logic [2:0] sc;
            sc = (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
            s  = (v[o] && out_ready[o]) ? sc : cur[o];
            gv[o] = 1'b0;
            gi[o] = 3'd0;
            if (!v[o] || out_ready[o]) begin
                for (int k = 0; k < 5; k++) begin
                    idx = s + 3'(k);
                    if (idx >= 3'd5) idx = idx - 3'd5;
                    if (!gv[o] && in_valid[idx] && dst[idx] == 3'(o)) begin
                        gv[o] = 1'b1;
                        gi[o] = idx;
                    end
                end
            end
        end
        for (int o = 0; o < 5; o++) begin
            if (gv[o] && !rst) in_ready[gi[o]] = 1'b1;
        end
    end

    // state
    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]   <= 1'b0;
                cur[o] <= 3'd0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gv[o]) begin
                    v[o]    <= 1'b1;
                    data[o] <= in_flit[gi[o]*F +: F];
                    src[o]  <= gi[o];
                end else if (out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]          v;
    logic [5*F-1:0]      data;
    logic [14:0]         src;
    logic [14:0]         cur;

    logic [24:0]         req;    // req[o*5+i]: input i requests output o
    logic [24:0]         grant;  // grant[o*5+i]
    logic [4:0]          gv;
    logic [14:0]         gi;

    // routing
    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] d;
        req = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F-1 -: 2];
            dy = in_flit[i*F + F-3 -: 2];
            if (dx > X)      d = 3'd2;
            else if (dx < X) d = 3'd3;
            else if (dy > Y) d = 3'd0;
            else if (dy < Y) d = 3'd1;
            else             d = 3'd4;
            for (int o = 0; o < 5; o++)
                req[o*5+i] = in_valid[i] && (d == 3'(o));
        end
    end

    // arbitration
    always_comb begin
        int s, idx, sc, sr;
        logic found;
        grant = '0;
        gv    = '0;
        gi    = '0;
        s = 0; idx = 0; sc = 0; sr = 0; found = 1'b0;
        for (int o = 0; o < 5; o++) begin
            sr = int'(src[o*3 +: 3]);
            sc = (sr >= 4) ? 0 : sr + 1;
            s  = (v[o] && out_ready[o]) ? sc : int'(cur[o*3 +: 3]);
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = s + k;
                if (idx >= 5) idx = idx - 5;
                if ((!v[o] || out_ready[o]) && !found && req[o*5+idx]) begin
                    found = 1'b1;
                    grant[o*5+idx] = 1'b1;
                    gi[o*3 +: 3] = 3'(idx);
                end
            end
            gv[o] = found;
        end
    end

    always_comb begin
        for (int i = 0; i < 5; i++)
            in_ready[i] = !rst && (grant[i] | grant[5+i] | grant[10+i] | grant[15+i] | grant[20+i]);
    end

    // state
    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o] <= 1'b0;
                cur[o*3 +: 3] <= 3'd0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o*3 +: 3] <= (src[o*3 +: 3] == 3'd4) ? 3'd0 : src[o*3 +: 3] + 3'd1;
                if (gv[o]) begin
                    v[o] <= 1'b1;
                    data[o*F +: F] <= in_flit[int'(gi[o*3 +: 3])*F +: F];
                    src[o*3 +: 3] <= gi[o*3 +: 3];
                end else if (out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o*F +: F] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]     v;
    logic [5*F-1:0] data;
    logic [24:0]    src;    // one-hot source of last stored/retired flit per output

    logic [24:0]    req;    // req[o*5+i]
    logic [24:0]    grant;  // grant[o*5+i]

    // routing
    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] d;
        req = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F-1 -: 2];
            dy = in_flit[i*F + F-3 -: 2];
            if (dx > X)      d = 3'd2;
            else if (dx < X) d = 3'd3;
            else if (dy > Y) d = 3'd0;
            else if (dy < Y) d = 3'd1;
            else             d = 3'd4;
            for (int o = 0; o < 5; o++)
                req[o*5+i] = in_valid[i] && (d == 3'(o));
        end
    end

    // arbitration: scan starts at successor of src
    always_comb begin
        logic [4:0] p, r;
        logic       avail, blk, done, g;
        int         idx;
        grant = '0;
        p = '0; r = '0; avail = 1'b0; blk = 1'b0; done = 1'b0; g = 1'b0; idx = 0;
        for (int o = 0; o < 5; o++) begin
            r     = req[o*5 +: 5];
            p     = {src[o*5 +: 4], src[o*5+4]};
            avail = !v[o] || out_ready[o];
            for (int i = 0; i < 5; i++) begin
                g = 1'b0;
                for (int j = 0; j < 5; j++) begin
                    blk  = 1'b0;
                    done = 1'b0;
                    for (int m = 0; m < 5; m++) begin
                        idx = (j + m) % 5;
                        if (idx == i) done = 1'b1;
                        if (!done) blk = blk | r[idx];
                    end
                    g = g | (p[j] & ~blk);
                end
                grant[o*5+i] = r[i] & g & avail;
            end
        end
    end

    always_comb begin
        for (int i = 0; i < 5; i++)
            in_ready[i] = !rst && (grant[i] | grant[5+i] | grant[10+i] | grant[15+i] | grant[20+i]);
    end

    // state
    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o] <= 1'b0;
                src[o*5 +: 5] <= 5'b10000;
            end else begin
                if (|grant[o*5 +: 5]) begin
                    logic [F-1:0] nd;
                    nd = '0;
                    for (int i = 0; i < 5; i++)
                        nd = nd | (in_flit[i*F +: F] & {F{grant[o*5+i]}});
                    v[o] <= 1'b1;
                    data[o*F +: F] <= nd;
                    src[o*5 +: 5] <= grant[o*5 +: 5];
                end else if (out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = data[o*F +: F] & {F{v[o]}};
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] fl  [5];
    logic [2:0]   src [5];
    logic [2:0]   cur [5];

    logic [2:0] dst [5];
    logic [4:0] gnt [5];
    logic [2:0] gsrc [5];
    logic [4:0] drain;
    logic [4:0] acc;

    logic [1:0] dx, dy;
    logic [2:0] start;
    logic       found;
    int         idx;

    always_comb begin
        in_ready = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F+PAYLOAD_W+2 +: 2];
            dy = in_flit[i*F+PAYLOAD_W +: 2];
            if (dx > X)      dst[i] = 3'd2;
            else if (dx < X) dst[i] = 3'd3;
            else if (dy > Y) dst[i] = 3'd0;
            else if (dy < Y) dst[i] = 3'd1;
            else             dst[i] = 3'd4;
        end
        for (int o = 0; o < 5; o++) begin
            drain[o] = v[o] & out_ready[o];
            if (drain[o]) start = (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
            else          start = cur[o];
            found   = 1'b0;
            gnt[o]  = '0;
            gsrc[o] = 3'd0;
            for (int k = 0; k < 5; k++) begin
                idx = int'(start) + k;
                if (idx >= 5) idx = idx - 5;
                if (!found && !rst && (!v[o] || out_ready[o]) &&
                    in_valid[idx] && (int'(dst[idx]) == o)) begin
                    found     = 1'b1;
                    gnt[o][idx] = 1'b1;
                    gsrc[o]   = 3'(idx);
                end
            end
            acc[o] = found;
            in_ready = in_ready | gnt[o];
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? fl[o] : '0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= '0;
            for (int o = 0; o < 5; o++) begin
                fl[o]  <= '0;
                src[o] <= 3'd0;
                cur[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (acc[o]) begin
                    v[o]   <= 1'b1;
                    fl[o]  <= in_flit[int'(gsrc[o])*F +: F];
                    src[o] <= gsrc[o];
                end else if (drain[o]) begin
                    v[o]   <= 1'b0;
                    fl[o]  <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] fl  [5];
    logic [4:0]   ptr [5];   // one-hot: successor of source of current/last flit

    logic [4:0] req [5];
    logic [4:0] gnt [5];
    logic [4:0] acc;

    logic [1:0] dx, dy;
    logic [4:0] th, mreq, pick, dec;
    logic [F-1:0] sel [5];

    always_comb begin
        for (int o = 0; o < 5; o++) req[o] = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F+PAYLOAD_W+2 +: 2];
            dy = in_flit[i*F+PAYLOAD_W +: 2];
            if (dx > X)      req[2][i] = in_valid[i];
            else if (dx < X) req[3][i] = in_valid[i];
            else if (dy > Y) req[0][i] = in_valid[i];
            else if (dy < Y) req[1][i] = in_valid[i];
            else             req[4][i] = in_valid[i];
        end

        in_ready = '0;
        for (int o = 0; o < 5; o++) begin
            th[0] = ptr[o][0];
            for (int k = 1; k < 5; k++) th[k] = th[k-1] | ptr[o][k];
            mreq = req[o] & th;
            pick = (|mreq) ? mreq : req[o];
            dec  = pick & (~pick + 5'd1);
            gnt[o] = (!rst && (!v[o] || out_ready[o])) ? dec : 5'b0;
            acc[o] = |gnt[o];
            in_ready = in_ready | gnt[o];
            sel[o] = '0;
            for (int i = 0; i < 5; i++)
                sel[o] = sel[o] | (in_flit[i*F +: F] & {F{gnt[o][i]}});
        end

        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = fl[o] & {F{v[o]}};
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= '0;
            for (int o = 0; o < 5; o++) ptr[o] <= 5'b00001;
        end else begin
            for (int o = 0; o < 5; o++) begin
                v[o] <= acc[o] | (v[o] & ~out_ready[o]);
                if (acc[o]) begin
                    fl[o]  <= sel[o];
                    ptr[o] <= {gnt[o][3:0], gnt[o][4]};
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [F-1:0] slot_flit [5];
    logic [2:0]   slot_src  [5];
    logic [2:0]   cursor    [5];
    logic [4:0]   slot_v;

    logic [2:0]   req  [5];
    logic [2:0]   gsel [5];
    logic [4:0]   gany;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic       found;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      req[i] = 3'd2;
            else if (dx < X) req[i] = 3'd3;
            else if (dy > Y) req[i] = 3'd0;
            else if (dy < Y) req[i] = 3'd1;
            else             req[i] = 3'd4;
        end
        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            start = (slot_v[o] && out_ready[o]) ? succ(slot_src[o]) : cursor[o];
            found = 1'b0;
            gsel[o] = 3'd0;
            for (int k = 0; k < 5; k++) begin
                idx = start + 3'(k);
                if (idx >= 3'd5) idx = idx - 3'd5;
                if (!found && (!slot_v[o] || out_ready[o]) && in_valid[idx] &&
                    req[idx] == 3'(o) && !rst) begin
                    found = 1'b1;
                    gsel[o] = idx;
                end
            end
            gany[o] = found;
            if (found) in_ready[gsel[o]] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            slot_v <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cursor[o]    <= 3'd0;
                slot_flit[o] <= '0;
                slot_src[o]  <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (slot_v[o] && out_ready[o])
                    cursor[o] <= succ(slot_src[o]);
                if (gany[o]) begin
                    slot_v[o]    <= 1'b1;
                    slot_flit[o] <= in_flit[gsel[o]*F +: F];
                    slot_src[o]  <= gsel[o];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = slot_v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = slot_v[o] ? slot_flit[o] : '0;
    end
endmodule

