module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] data [5];
    logic [2:0]   cur  [5];
    logic [2:0]   src  [5];

    logic [4:0]   req [5];     // req[o][i]: input i requests output o
    logic [4:0]   gv;          // grant valid per output
    logic [2:0]   gs [5];      // granted source per output
    logic [4:0]   drain;

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic [3:0] sum;
        for (int o = 0; o < 5; o++) req[o] = 5'b0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (in_valid[i]) begin
                if (dx > X)      req[2][i] = 1'b1;
                else if (dx < X) req[3][i] = 1'b1;
                else if (dy > Y) req[0][i] = 1'b1;
                else if (dy < Y) req[1][i] = 1'b1;
                else             req[4][i] = 1'b1;
            end
        end
        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            drain[o] = v[o] & out_ready[o];
            if (v[o]) start = (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
            else      start = cur[o];
            gv[o] = 1'b0;
            gs[o] = 3'd0;
            if (!rst && (!v[o] || out_ready[o])) begin
                for (int k = 0; k < 5; k++) begin
                    sum = {1'b0, start} + 4'(k);
                    if (sum >= 4'd5) sum = sum - 4'd5;
                    idx = sum[2:0];
                    if (!gv[o] && req[o][idx]) begin
                        gv[o] = 1'b1;
                        gs[o] = idx;
                    end
                end
            end
            if (gv[o]) in_ready[gs[o]] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cur[o]  <= 3'd0;
                src[o]  <= 3'd0;
                data[o] <= '0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gv[o]) begin
                    v[o]    <= 1'b1;
                    data[o] <= in_flit[gs[o]*F +: F];
                    src[o]  <= gs[o];
                end else if (drain[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    assign out_valid = v;
    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
