module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [14:0] tgt;          // 3-bit target output per input
    logic [4:0]  rdyo [5];     // per-output grant to inputs

    genvar gi, go;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_in
            wire [1:0] dx = in_flit[gi*F + PAYLOAD_W + 2 +: 2];
            wire [1:0] dy = in_flit[gi*F + PAYLOAD_W +: 2];
            assign tgt[gi*3 +: 3] = (dx > X) ? 3'd2 :
                                    (dx < X) ? 3'd3 :
                                    (dy > Y) ? 3'd0 :
                                    (dy < Y) ? 3'd1 : 3'd4;
        end
    endgenerate

    generate
        for (go = 0; go < 5; go++) begin : g_out
            logic         v;
            logic [F-1:0] data;
            logic [2:0]   cur;
            logic [2:0]   src;
            logic [4:0]   rq;
            logic         gv;
            logic [2:0]   gs;
            logic [2:0]   nxt;
            logic         drain;

            assign nxt   = (src == 3'd4) ? 3'd0 : src + 3'd1;
            assign drain = v & out_ready[go];

            always_comb begin
                logic [2:0] start, idx;
                logic [3:0] sum;
                logic       avail;
                for (int i = 0; i < 5; i++)
                    rq[i] = in_valid[i] && (tgt[i*3 +: 3] == 3'(go));
                start = v ? nxt : cur;
                avail = !rst && (!v || out_ready[go]);
                idx = 3'd0;
                sum = 4'd0;
                gv = 1'b0;
                gs = 3'd0;
                for (int k = 0; k < 5; k++) begin
                    sum = {1'b0, start} + 4'(k);
                    if (sum >= 4'd5) sum = sum - 4'd5;
                    idx = sum[2:0];
                    if (avail && !gv && rq[idx]) begin
                        gv = 1'b1;
                        gs = idx;
                    end
                end
                for (int i = 0; i < 5; i++)
                    rdyo[go][i] = gv && (gs == 3'(i));
            end

            always_ff @(posedge clk) begin
                if (rst) begin
                    v    <= 1'b0;
                    cur  <= 3'd0;
                    src  <= 3'd0;
                    data <= '0;
                end else begin
                    if (drain) cur <= nxt;
                    if (gv) begin
                        v    <= 1'b1;
                        data <= in_flit[gs*F +: F];
                        src  <= gs;
                    end else if (drain) begin
                        v <= 1'b0;
                    end
                end
            end

            assign out_valid[go]        = v;
            assign out_flit[go*F +: F]  = v ? data : '0;
        end
    endgenerate

    assign in_ready = rdyo[0] | rdyo[1] | rdyo[2] | rdyo[3] | rdyo[4];
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] data [5];
    logic [2:0]   src  [5];
    logic [2:0]   cur  [5];

    logic [2:0] dest [5];      // requested output per input
    logic [4:0] gnt  [5];      // gnt[o][i]
    logic       gany [5];
    logic [2:0] gsrc [5];

    always_comb begin
        for (int i = 0; i < 5; i++) begin
            logic [1:0] dx, dy;
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      dest[i] = 3'd2;
            else if (dx < X) dest[i] = 3'd3;
            else if (dy > Y) dest[i] = 3'd0;
            else if (dy < Y) dest[i] = 3'd1;
            else             dest[i] = 3'd4;
        end

        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            int s;
            int idx;
            logic found;
            logic avail;
            avail = !v[o] || out_ready[o];
            if (v[o]) s = (src[o] == 3'd4) ? 0 : int'(src[o]) + 1;
            else      s = int'(cur[o]);
            gnt[o]  = 5'b0;
            gany[o] = 1'b0;
            gsrc[o] = 3'd0;
            found   = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if (avail && !found && in_valid[idx] && dest[idx] == 3'(o)) begin
                    found = 1'b1;
                    gnt[o][idx] = 1'b1;
                    gany[o] = 1'b1;
                    gsrc[o] = 3'(idx);
                end
            end
            if (!rst) in_ready = in_ready | gnt[o];
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]   <= 1'b0;
                cur[o] <= 3'd0;
                src[o] <= 3'd0;
                data[o] <= '0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gany[o]) begin
                    v[o]    <= 1'b1;
                    src[o]  <= gsrc[o];
                    data[o] <= in_flit[int'(gsrc[o])*F +: F];
                end else if (v[o] && out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]          v;
    logic [4:0][F-1:0]   data;
    logic [4:0][4:0]     src;   // one-hot source of held flit
    logic [4:0][4:0]     cur;   // one-hot cursor
    logic [4:0][4:0]     dsel;  // dsel[i][o]: input i requests output o
    logic [4:0][4:0]     gnt;   // gnt[o][i]

    function automatic logic [4:0] rotl1(input logic [4:0] a);
        return {a[3:0], a[4]};
    endfunction

    // one-hot start, request vector -> one-hot grant
    function automatic logic [4:0] pick(input logic [4:0] r, input logic [4:0] s);
        logic [4:0] g;
        logic f;
        g = 5'b0;
        for (int st = 0; st < 5; st++) begin
            if (s[st]) begin
                f = 1'b0;
                for (int k = 0; k < 5; k++) begin
                    g[(st + k) % 5] = !f && r[(st + k) % 5];
                    f = f | r[(st + k) % 5];
                end
            end
        end
        return g;
    endfunction

    genvar i, o;
    generate
        for (i = 0; i < 5; i++) begin : g_route
            wire [1:0] dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            wire [1:0] dy = in_flit[i*F + PAYLOAD_W +: 2];
            wire gx = dx > X;
            wire lx = dx < X;
            wire ex = dx == X;
            wire gy = dy > Y;
            wire ly = dy < Y;
            wire ey = dy == Y;
            assign dsel[i][2] = in_valid[i] & gx;
            assign dsel[i][3] = in_valid[i] & lx;
            assign dsel[i][0] = in_valid[i] & ex & gy;
            assign dsel[i][1] = in_valid[i] & ex & ly;
            assign dsel[i][4] = in_valid[i] & ex & ey;
        end

        for (o = 0; o < 5; o++) begin : g_out
            wire        avail = !v[o] || out_ready[o];
            wire [4:0]  req   = {dsel[4][o], dsel[3][o], dsel[2][o], dsel[1][o], dsel[0][o]};
            wire [4:0]  start = v[o] ? rotl1(src[o]) : cur[o];
            assign gnt[o] = avail ? pick(req, start) : 5'b0;

            logic [F-1:0] nd;
            always_comb begin
                nd = '0;
                for (int k = 0; k < 5; k++)
                    nd = nd | (in_flit[k*F +: F] & {F{gnt[o][k]}});
            end

            wire gany = |gnt[o];

            always_ff @(posedge clk) begin
                if (rst) begin
                    v[o]   <= 1'b0;
                    cur[o] <= 5'b00001;
                    src[o] <= 5'b00001;
                end else begin
                    if (v[o] && out_ready[o])
                        cur[o] <= rotl1(src[o]);
                    if (gany) begin
                        v[o]    <= 1'b1;
                        src[o]  <= gnt[o];
                        data[o] <= nd;
                    end else if (v[o] && out_ready[o]) begin
                        v[o] <= 1'b0;
                    end
                end
            end

            assign out_flit[o*F +: F] = data[o] & {F{v[o]}};
        end

        for (i = 0; i < 5; i++) begin : g_rdy
            assign in_ready[i] = !rst & (gnt[0][i] | gnt[1][i] | gnt[2][i] | gnt[3][i] | gnt[4][i]);
        end
    endgenerate

    assign out_valid = v;
endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);
    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;
    logic [31:0] ctrl, scratch, irq;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    logic [31:0] wmask;
    assign wmask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    logic commit;
    assign commit = aw_full && w_full;

    logic wr_ok;
    assign wr_ok = (aw_addr[1:0] == 2'b00) && (aw_addr[3:2] != 2'b01);

    logic        rd_ok;
    logic [31:0] rd_val;
    assign rd_ok = (s_axi_araddr[1:0] == 2'b00);
    always_comb begin
        case (s_axi_araddr[3:2])
            2'd0:    rd_val = ctrl;
            2'd1:    rd_val = status_in;
            2'd2:    rd_val = scratch;
            default: rd_val = irq;
        endcase
        if (!rd_ok) rd_val = 32'd0;
    end

    logic [31:0] clr_mask;
    assign clr_mask = (commit && wr_ok && aw_addr[3:2] == 2'd3) ? (w_data & wmask) : 32'd0;

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'd0;
            w_data       <= 32'd0;
            w_strb       <= 4'd0;
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= (irq & ~clr_mask) | irq_set;

            // write address / data slots
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_ok ? 2'b00 : 2'b10;
                if (wr_ok) begin
                    if (aw_addr[3:2] == 2'd0)
                        ctrl <= (ctrl & ~wmask) | (w_data & wmask);
                    else if (aw_addr[3:2] == 2'd2)
                        scratch <= (scratch & ~wmask) | (w_data & wmask);
                end
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // read
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_val;
                s_axi_rresp  <= (rd_ok && s_axi_araddr[3:2] != 2'b00 || rd_ok && s_axi_araddr[3:2] == 2'b00)
                                ? 2'b00 : 2'b10;
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end
endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic [31:0] ctrl, scratch, irq;
    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    logic [31:0] strb_mask;
    assign strb_mask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    logic commit;
    assign commit = aw_full && w_full;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl         <= 32'b0;
            scratch      <= 32'b0;
            irq          <= 32'b0;
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'b0;
            w_data       <= 32'b0;
            w_strb       <= 4'b0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'b0;
            s_axi_rresp  <= 2'b00;
        end else begin
            // IRQ set (default path)
            irq <= irq | irq_set;

            // Write address / data capture
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            // Write commit
            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                if (aw_addr[1:0] != 2'b00 || aw_addr == 4'h4) begin
                    s_axi_bresp <= 2'b10;
                end else begin
                    s_axi_bresp <= 2'b00;
                    case (aw_addr[3:2])
                        2'd0: ctrl    <= (ctrl & ~strb_mask) | (w_data & strb_mask);
                        2'd2: scratch <= (scratch & ~strb_mask) | (w_data & strb_mask);
                        2'd3: irq     <= (irq & ~(w_data & strb_mask)) | irq_set;
                        default: ;
                    endcase
                end
            end

            if (s_axi_bvalid && s_axi_bready)
                s_axi_bvalid <= 1'b0;

            // Read
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                if (s_axi_araddr[1:0] != 2'b00) begin
                    s_axi_rdata <= 32'b0;
                    s_axi_rresp <= 2'b10;
                end else begin
                    s_axi_rresp <= 2'b00;
                    case (s_axi_araddr[3:2])
                        2'd0: s_axi_rdata <= ctrl;
                        2'd1: s_axi_rdata <= status_in;
                        2'd2: s_axi_rdata <= scratch;
                        default: s_axi_rdata <= irq;
                    endcase
                end
            end

            if (s_axi_rvalid && s_axi_rready)
                s_axi_rvalid <= 1'b0;
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic [31:0] ctrl, scratch, irq;
    logic        aw_have, w_have;
    logic [3:0]  aw_addr, w_strb;
    logic [31:0] w_data;
    logic        bvalid, rvalid;
    logic [1:0]  bresp, rresp;
    logic [31:0] rdata;

    assign s_axi_awready = !aw_have && !bvalid && !rst;
    assign s_axi_wready  = !w_have  && !bvalid && !rst;
    assign s_axi_arready = !rvalid && !rst;
    assign s_axi_bvalid  = bvalid;
    assign s_axi_bresp   = bresp;
    assign s_axi_rvalid  = rvalid;
    assign s_axi_rresp   = rresp;
    assign s_axi_rdata   = rdata;

    logic [31:0] bmask;
    assign bmask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    logic commit;
    assign commit = aw_have && w_have;

    logic        w_aligned, w_ok;
    assign w_aligned = (aw_addr[1:0] == 2'b00);
    assign w_ok = w_aligned && (aw_addr[3:2] != 2'd1);

    logic [31:0] clr;
    assign clr = (commit && w_ok && aw_addr[3:2] == 2'd3) ? (w_data & bmask) : 32'd0;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl    <= 32'd0;
            scratch <= 32'd0;
            irq     <= 32'd0;
            aw_have <= 1'b0;
            w_have  <= 1'b0;
            aw_addr <= 4'd0;
            w_data  <= 32'd0;
            w_strb  <= 4'd0;
            bvalid  <= 1'b0;
            bresp   <= 2'b00;
            rvalid  <= 1'b0;
            rresp   <= 2'b00;
            rdata   <= 32'd0;
        end else begin
            irq <= (irq & ~clr) | irq_set;

            // write address / data slots
            if (s_axi_awvalid && s_axi_awready) begin
                aw_have <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_have <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            if (commit) begin
                aw_have <= 1'b0;
                w_have  <= 1'b0;
                bvalid  <= 1'b1;
                bresp   <= w_ok ? 2'b00 : 2'b10;
                if (w_ok) begin
                    if (aw_addr[3:2] == 2'd0)
                        ctrl <= (ctrl & ~bmask) | (w_data & bmask);
                    else if (aw_addr[3:2] == 2'd2)
                        scratch <= (scratch & ~bmask) | (w_data & bmask);
                end
            end else if (bvalid && s_axi_bready) begin
                bvalid <= 1'b0;
            end

            // read channel
            if (s_axi_arvalid && s_axi_arready) begin
                rvalid <= 1'b1;
                if (s_axi_araddr[1:0] != 2'b00) begin
                    rdata <= 32'd0;
                    rresp <= 2'b10;
                end else begin
                    rresp <= 2'b00;
                    case (s_axi_araddr[3:2])
                        2'd0:    rdata <= ctrl;
                        2'd1:    rdata <= status_in;
                        2'd2:    rdata <= scratch;
                        default: rdata <= irq;
                    endcase
                end
            end else if (rvalid && s_axi_rready) begin
                rvalid <= 1'b0;
            end
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic [31:0] ctrl, scratch, irq;
    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    wire commit = aw_full && w_full;

    logic [31:0] bmask;
    assign bmask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    logic [31:0] clr;
    assign clr = w_data & bmask;

    logic wr_ok;
    assign wr_ok = (aw_addr == 4'h0) || (aw_addr == 4'h8) || (aw_addr == 4'hC);

    logic [31:0] rd_val;
    logic        rd_ok;
    always_comb begin
        rd_ok  = 1'b1;
        rd_val = 32'd0;
        case (s_axi_araddr)
            4'h0:    rd_val = ctrl;
            4'h4:    rd_val = status_in;
            4'h8:    rd_val = scratch;
            4'hC:    rd_val = irq;
            default: begin rd_ok = 1'b0; rd_val = 32'd0; end
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'd0;
            w_data       <= 32'd0;
            w_strb       <= 4'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= irq | irq_set;

            // write address / data capture
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            // write commit
            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_ok ? 2'b00 : 2'b10;
                case (aw_addr)
                    4'h0: ctrl    <= (ctrl & ~bmask) | (w_data & bmask);
                    4'h8: scratch <= (scratch & ~bmask) | (w_data & bmask);
                    4'hC: irq     <= (irq & ~clr) | irq_set;
                    default: ;
                endcase
            end

            if (s_axi_bvalid && s_axi_bready)
                s_axi_bvalid <= 1'b0;

            // read
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_val;
                s_axi_rresp  <= rd_ok ? 2'b00 : 2'b10;
            end
            if (s_axi_rvalid && s_axi_rready)
                s_axi_rvalid <= 1'b0;
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);
    logic [31:0] ctrl, scratch, irq;
    logic        aw_have, w_have;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    logic [31:0] bmask;
    logic        commit;

    assign s_axi_awready = !aw_have && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_have  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign bmask  = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};
    assign commit = aw_have && w_have;

    logic [31:0] clr;
    assign clr = (commit && aw_addr == 4'hC) ? (w_data & bmask) : 32'h0;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl         <= 32'h0;
            scratch      <= 32'h0;
            irq          <= 32'h0;
            aw_have      <= 1'b0;
            w_have       <= 1'b0;
            aw_addr      <= 4'h0;
            w_data       <= 32'h0;
            w_strb       <= 4'h0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'h0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= (irq & ~clr) | irq_set;

            // write address / data slots
            if (s_axi_awvalid && s_axi_awready) begin
                aw_have <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_have <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            if (commit) begin
                aw_have      <= 1'b0;
                w_have       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                case (aw_addr)
                    4'h0: begin
                        ctrl        <= (ctrl & ~bmask) | (w_data & bmask);
                        s_axi_bresp <= 2'b00;
                    end
                    4'h8: begin
                        scratch     <= (scratch & ~bmask) | (w_data & bmask);
                        s_axi_bresp <= 2'b00;
                    end
                    4'hC:    s_axi_bresp <= 2'b00;
                    default: s_axi_bresp <= 2'b10;
                endcase
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // read channel
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                case (s_axi_araddr)
                    4'h0: begin s_axi_rdata <= ctrl;      s_axi_rresp <= 2'b00; end
                    4'h4: begin s_axi_rdata <= status_in; s_axi_rresp <= 2'b00; end
                    4'h8: begin s_axi_rdata <= scratch;   s_axi_rresp <= 2'b00; end
                    4'hC: begin s_axi_rdata <= irq;       s_axi_rresp <= 2'b00; end
                    default: begin s_axi_rdata <= 32'h0;  s_axi_rresp <= 2'b10; end
                endcase
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end
endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Pipeline: edge k captures operands (s1), k+1 multiplies (s2),
    // k+2 passes (s3), k+3 drives outputs.
    logic signed [WIDTH-1:0]   a1, b1;
    logic                      v1;
    logic signed [2*WIDTH-1:0] p2, p3;
    logic                      v2, v3;

    always_ff @(posedge clk) begin
        if (rst) begin
            a1        <= '0;
            b1        <= '0;
            v1        <= 1'b0;
            p2        <= '0;
            v2        <= 1'b0;
            p3        <= '0;
            v3        <= 1'b0;
            product   <= '0;
            out_valid <= 1'b0;
        end else begin
            // stage 1: capture operands (zeroed on bubble)
            v1 <= in_valid;
            a1 <= in_valid ? a : '0;
            b1 <= in_valid ? b : '0;
            // stage 2: multiply (zero operands give zero on bubbles)
            v2 <= v1;
            p2 <= a1 * b1;
            // stage 3
            v3 <= v2;
            p3 <= p2;
            // output stage
            out_valid <= v3;
            product   <= p3;
        end
    end

endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    logic signed [WIDTH-1:0]   a1, b1;
    logic                      v1, v2, v3;
    logic signed [2*WIDTH-1:0] p2, p3;
    logic signed [2*WIDTH-1:0] prod_w;

    assign prod_w = a1 * b1;

    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            p2        <= '0;
            p3        <= '0;
            product   <= '0;
        end else begin
            v1 <= in_valid;
            v2 <= v1;
            v3 <= v2;
            out_valid <= v3;
            p2      <= v1 ? prod_w : '0;
            p3      <= p2;
            product <= p3;
        end
    end

    always_ff @(posedge clk) begin
        a1 <= a;
        b1 <= b;
    end

endmodule

module mul_pipe3 #(
