    logic signed [WIDTH-1:0]   a1, b1;
    logic signed [2*WIDTH-1:0] p2, p3;

    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            a1        <= '0;
            b1        <= '0;
            p2        <= '0;
            p3        <= '0;
            product   <= '0;
        end else begin
            // stage 1: capture
            v1 <= in_valid;
            a1 <= in_valid ? a : '0;
            b1 <= in_valid ? b : '0;
            // stage 2: multiply
            v2 <= v1;
            p2 <= v1 ? (a1 * b1) : '0;
            // stage 3: pass
            v3 <= v2;
            p3 <= p2;
            // stage 4: output
            out_valid <= v3;
            product   <= p3;
        end
    end

endmodule

